from pathlib import Path
import json, re

HOME=Path.home()
STATE_ROOT=HOME/".local/state/prediction-project-executor"
CAMPAIGN=HOME/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
N1E36="DEV-PRED-A2Z-DIRECT-SOL-REGRESSION-N1E36-20261007"
ASTRA="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
PROPOSAL="A2Z-V4-SOL-PROPOSAL-DIRECT-20261007-R4P2"
OLD_SOL="A2Z-V4-SOL-BUILD-20261007-R4"

def load(p):
    return json.loads(p.read_text(encoding="utf-8"))

def dump(label,obj,limit=12000):
    s=json.dumps(obj,ensure_ascii=False,sort_keys=True,separators=(",",":"))
    if len(s)>limit: s=s[:limit]+"...<TRUNCATED>"
    print(label+"="+s)

# 1) Existing regression proof: do not rerun anything.
sp=STATE_ROOT/(N1E36+".json")
if not sp.is_file():
    raise RuntimeError("N1E36_STATE_MISSING")
st=load(sp)
dump("N1E36_STATE",st)
blob=json.dumps(st,ensure_ascii=False,sort_keys=True)
status=str(st.get("status") or "").upper()
exit_code=st.get("exit_code")
if exit_code is None:
    # Some receipts record per-operation rc only; infer only if explicit persisted rc(s) exist and all are zero.
    rcs=[]
    def walk(v):
        if isinstance(v,dict):
            for k,x in v.items():
                if k in {"rc","returncode","exit_code"} and isinstance(x,int):
                    rcs.append(x)
                walk(x)
        elif isinstance(v,list):
            for x in v: walk(x)
    walk(st)
    if rcs and all(x==0 for x in rcs):
        exit_code=0
if status!="PASS" or exit_code!=0:
    raise RuntimeError("N1E36_NOT_PASS status=%r exit=%r"%(status,exit_code))
if "tests/model_execution/test_direct_sol_chat.py" not in blob or "unittest" not in blob:
    raise RuntimeError("N1E36_TARGET_TEST_NOT_PROVEN")
print("N1E36_PROOF=PASS")

# 2) Exact Astra request.
req=CAMPAIGN/"requests"/(ASTRA+".json")
if not req.is_file():
    raise RuntimeError("ASTRA_REQUEST_MISSING")
ro=load(req)
dump("ASTRA_REQUEST",ro)
if ro.get("task_id")!=ASTRA:
    raise RuntimeError("ASTRA_REQUEST_TASK_MISMATCH")
if ro.get("phase")!="ASTRA_PREBUILD":
    raise RuntimeError("ASTRA_REQUEST_PHASE_MISMATCH")
if ro.get("model_policy")!="ASTRA_EXACT":
    raise RuntimeError("ASTRA_REQUEST_POLICY_MISMATCH")

request_blob=json.dumps(ro,ensure_ascii=False,sort_keys=True)
if OLD_SOL in request_blob:
    raise RuntimeError("ASTRA_REQUEST_CONTAINS_OLD_SOL_BUILD")
if re.search(r"codex.*resume|resume.*codex",request_blob,re.I):
    raise RuntimeError("ASTRA_REQUEST_CONTAINS_CODEX_RESUME")

# Require explicit R4P2 proposal binding somewhere in the request.
if PROPOSAL not in request_blob:
    raise RuntimeError("ASTRA_REQUEST_PROPOSAL_BINDING_MISSING")
print("ASTRA_REQUEST_BINDING=PASS")

# 3) Existing result must still be absent; duplicate review prevention.
res=CAMPAIGN/"model_results"/(ASTRA+".json")
print("ASTRA_RESULT_EXISTS="+str(res.is_file()))
if res.is_file():
    existing=load(res)
    dump("ASTRA_EXISTING_RESULT",existing)
    raise RuntimeError("ASTRA_RESULT_ALREADY_EXISTS_DUPLICATE_RISK")

# 4) Inspect model control state / queue files and run dirs read-only.
models=CAMPAIGN/"models"
interesting=[]
if models.exists():
    for p in sorted(models.rglob("*")):
        if not p.is_file():
            continue
        rel=str(p.relative_to(CAMPAIGN))
        # Bound output; only metadata-ish files.
        if p.name.lower() in {"state.json","queue.json","task.json","worker.json","complete.json","request.json"} or "queue" in p.name.lower():
            try:
                txt=p.read_text(encoding="utf-8")
            except Exception:
                continue
            if len(txt)>20000: txt=txt[:20000]
            if ASTRA in txt or OLD_SOL in txt or "ASTRA_PREBUILD" in txt or "SOL_BUILD" in txt:
                interesting.append((rel,txt))
for rel,txt in interesting[:30]:
    print("MODEL_META_FILE="+rel)
    print("MODEL_META="+txt.replace("\n"," ")[:12000])

# Find exact run dirs for requested Astra task; must be zero before resuming to avoid duplicate in-flight execution.
runs=models/"runs"
astra_runs=sorted([p.name for p in runs.glob(ASTRA+"*") if p.is_dir()]) if runs.exists() else []
old_runs=sorted([p.name for p in runs.glob(OLD_SOL+"*") if p.is_dir()]) if runs.exists() else []
dump("ASTRA_RUN_DIRS",astra_runs)
dump("OLD_SOL_RUN_DIRS_LAST5",old_runs[-5:])
if astra_runs:
    raise RuntimeError("ASTRA_EXISTING_RUN_DIR_DUPLICATE_RISK")

# Queue runnable safety: fail if any metadata containing requested Astra also binds it to old Sol or resume.
for rel,txt in interesting:
    if ASTRA in txt:
        if OLD_SOL in txt:
            raise RuntimeError("QUEUE_BINDING_MIXES_ASTRA_AND_OLD_SOL file="+rel)
        if re.search(r"codex.*resume|resume.*codex",txt,re.I):
            raise RuntimeError("QUEUE_BINDING_HAS_CODEX_RESUME file="+rel)

print("PREBUILD_BINDING_READONLY=PASS")
